"use strict";(self.webpackChunkproblem_solving=self.webpackChunkproblem_solving||[]).push([[4307],{2678:e=>{e.exports=JSON.parse('{"tag":{"label":"Mid Level","permalink":"/problem-solving/tags/mid-level","allTagsPath":"/problem-solving/tags","count":5,"items":[{"id":"LeetCode/Minimum Changes To Make Alternating Binary String/README","title":"1758. Minimum Changes To Make Alternating Binary String","description":"You are given a string s consisting only of the characters \'0\' and \'1\'. In one operation, you can change any \'0\' to \'1\' or vice versa. The string is called alternating if no two adjacent characters are equal. For example, the string \\"010\\" is alternating, while the string \\"0100\\" is not. Return the minimum number of operations needed to make s alternating.","permalink":"/problem-solving/LeetCode/Minimum Changes To Make Alternating Binary String/"},{"id":"LeetCode/Concatenate Non-Zero Digits and Multiply by Sum I/README","title":"3754. Concatenate Non-Zero Digits and Multiply by Sum I","description":"You are given an integer n. Form a new integer x by concatenating all the non-zero digits of n in their original order. If there are no non-zero digits, x = 0. Let sum be the sum of digits in x. Return an integer representing the value of x * sum.","permalink":"/problem-solving/LeetCode/Concatenate Non-Zero Digits and Multiply by Sum I/"},{"id":"LeetCode/Count Commas in Range/README","title":"3870. Count Commas in Range","description":"You are given an integer n.Return the total number of commas used when writing all integers from [1, n] (inclusive) in standard number formatting.In standard formatting:A comma is inserted after every three digits from the right.Numbers with fewer than 4 digits contain no commas.","permalink":"/problem-solving/LeetCode/Count Commas in Range/"},{"id":"LeetCode/Smallest Stable Index I/README","title":"3903. Smallest Stable Index I","description":"You are given an integer array nums of length n and an integer k. For each index i, define its instability score as max(nums[0..i]) - min(nums[i..n - 1]).In other words max(nums[0..i]) is the largest value among the elements from index 0 to index i.min(nums[i..n - 1]) is the smallest value among the elements from index i to index n - 1.An index i is called stable if its instability score is less than or equal to k.Return the smallest stable index. If no such index exists, return -1.","permalink":"/problem-solving/LeetCode/Smallest Stable Index I/"},{"id":"LeetCode/Smallest Stable Index II/README","title":"3904. Smallest Stable Index II","description":"You are given an integer array nums of length n and an integer k.For each index i, define its instability score as max(nums[0..i]) - min(nums[i..n - 1]).In other words:max(nums[0..i]) is the largest value among the elements from index 0 to index i.min(nums[i..n - 1]) is the smallest value among the elements from index i to index n - 1.An index i is called stable if its instability score is less than or equal to k.Return the smallest stable index. If no such index exists, return -1.","permalink":"/problem-solving/LeetCode/Smallest Stable Index II/"}],"unlisted":false}}')}}]);